"""Static validation of webhook_endpoint.py using only the stdlib (ast)."""

import ast
import sys
from pathlib import Path

TARGET = Path("webhook_endpoint.py")

failures = []

# 1. Parse to confirm valid Python syntax.
try:
    tree = ast.parse(TARGET.read_text(encoding="utf-8"), filename=str(TARGET))
    print(f"[OK] {TARGET} parses as valid Python")
except SyntaxError as exc:
    print(f"[FAIL] Syntax error: {exc}")
    sys.exit(1)

func_names = {node.name for node in ast.walk(tree) if isinstance(node, ast.FunctionDef)}
route_targets = []

for node in ast.walk(tree):
    if isinstance(node, ast.FunctionDef) and node.decorator_list:
        for dec in node.decorator_list:
            if isinstance(dec, ast.Call) and getattr(dec.func, "id", "") == "app.route":
                if dec.args and isinstance(dec.args[0], ast.Constant):
                    route_targets.append(dec.args[0].value)

checks = [
    ("webhook endpoint function defined", "webhook" in func_names),
    ("payment_intent.succeeded handler defined", "handle_successful_payment" in func_names),
    ("payment_intent.payment_failed handler defined", "handle_failed_payment" in func_names),
    ("event dispatch function defined", "dispatch_event" in func_names),
    ("idempotency check function defined", "is_event_processed" in func_names),
    ("idempotency mark function defined", "mark_event_processed" in func_names),
    ("signature verification present (construct_event)", "construct_event" in TARGET.read_text()),
    ("webhook route registered", "/webhook" in route_targets),
]

for label, ok in checks:
    print(f"[{'OK' if ok else 'FAIL'}] {label}")
    if not ok:
        failures.append(label)

# 2. Verify both event types appear as dispatch branches.
source = TARGET.read_text(encoding="utf-8")
for event_type in ("payment_intent.succeeded", "payment_intent.payment_failed"):
    if f'"{event_type}"' not in source and f"'{event_type}'" not in source:
        print(f"[FAIL] event type {event_type} not handled")
        failures.append(event_type)
    else:
        print(f"[OK] event type {event_type} handled")

# 3. Verify the two required HTTP error paths (400/500) exist.
for code, reason in (("400", "bad payload/signature"), ("500", "processing failure / retry")):
    if code in source:
        print(f"[OK] returns HTTP {code} on {reason}")
    else:
        print(f"[FAIL] missing HTTP {code} return path")
        failures.append(f"HTTP {code}")

print()
if failures:
    print(f"VALIDATION FAILED: {failures}")
    sys.exit(1)
print("VALIDATION PASSED: webhook endpoint is syntactically valid and handles both events.")

